let sel = $input.first().json.output[0].content[0].text;
if (typeof sel === 'string') {
  sel = JSON.parse(sel.replace(/^```json\s*/i, '').replace(/```\s*$/, ''));
}
if (!sel.topic || !Array.isArray(sel.knowledge_tags) || !Array.isArray(sel.selected_sources) || sel.selected_sources.length < 2) {
  throw new Error('選題輸出格式不正確：' + JSON.stringify(sel).slice(0, 200));
}
return [{ json: sel }];

const sel = $('統一選題').first().json;
const plan = $('排程決策').first().json;
const entries = $input.first().json.entries || [];
if (entries.length === 0) throw new Error('知識庫查無相關條目，請檢查 knowledge_tags');
const BRIEF = {
  news: '時事觀點：引用並評論外部新聞，提出紫微斗數角度的具體判斷。',
  life: '人生議題：寫一個各國讀者都會遇到的生活問題（感情、金錢、工作、家庭、人生階段、身心），用紫微斗數提供看待方式；不要依附台灣在地新聞，但文中也不要刻意寫「各地讀者」「不同國家的人」這類字眼。',
  lesson: '紫微入門：教學文，讓沒學過的讀者讀完能真正理解一個概念，並澄清常見誤解。',
  monthly: '流月四化：本月運勢專欄，用一句主題當開場，說明本月四化星各自引動的生活面向；必須提醒流月要疊合個人命盤，不做生肖式吉凶排名。',
  solar_term: '二十四節氣：結合節氣的季節特性與宮位象徵，談作息、心態與留意事項；不談開運、不做吉凶斷語。',
  annual: '年度四化：明年流年四化總覽，談整體氛圍與不同命盤結構的人各自要留意什麼；避免生肖排名式預言。',
};
const sources = sel.selected_sources || [];
// 依標籤與主題字詞重合度挑出最相關的舊文，提高站內連結命中率
const kw = new Set([...(sel.knowledge_tags || []), ...String(sel.topic || '').split('')]);
const score = l => (l.tags || []).filter(t => kw.has(t)).length * 3 + l.title.split('').filter(c => kw.has(c)).length;
const suggested = [...plan.linkables].sort((x, y) => score(y) - score(x)).slice(0, 6);
const prompt = `文章類型：${sel.type_label}
寫作任務：${BRIEF[sel.type]}
主題：${sel.topic}
切角：${sel.angle}
${sel.case_idea ? `案例方向：${sel.case_idea}\n` : ''}${sel.facts ? `本篇必須使用、不得更改的事實資料：\n${JSON.stringify(sel.facts, null, 1)}\n` : ''}
外部來源${sources.length ? '（文中具名引述，文末「## 參考資料」逐篇附上連結）' : '：本篇沒有外部來源，「## 參考資料」改列理論出處書目，不需要連結'}：
${JSON.stringify(sources, null, 1)}

站內連結：內文必須插入 ${sel.min_internal}-4 個站內連結（少於 ${sel.min_internal} 個會被退稿），只能使用下列網址並原封照抄。
建議優先使用（與本篇最相關）：
${JSON.stringify(suggested, null, 1)}
完整舊文清單：
${JSON.stringify(plan.linkables.map(l => ({ title: l.title, url: l.url })), null, 1)}

知識庫條目（理論依據，引用論點時標明 source）：
${JSON.stringify(entries, null, 1)}

近期已發文標題（新標題句式不得與其相似）：
${JSON.stringify(plan.recentTitles)}`;
return [{ json: { prompt } }];

