let a = $('王老師寫作').first().json.output[0].content[0].text;
if (typeof a === 'string') a = JSON.parse(a.replace(/^```json\s*/i, '').replace(/```\s*$/, ''));
// 文筆審查是 OpenAI 節點，結果包在 output[0].content[0].text 裡，必須解開
let review = $input.first().json;
try {
  const t = review.output[0].content[0].text;
  review = typeof t === 'string' ? JSON.parse(t) : t;
} catch (e) { review = {}; }
const sel = $('統一選題').first().json;
const plan = $('排程決策').first().json;
const errors = [];
const content = a.content || '';
const len = content.replace(/\s/g, '').length;
if (len < 1800) errors.push(`字數不足：${len} < 1800`);
const refIdx = content.indexOf('## 參考資料');
if (refIdx === -1) errors.push('缺少「## 參考資料」區塊');
const body = refIdx === -1 ? content : content.slice(0, refIdx);
const refs = refIdx === -1 ? '' : content.slice(refIdx);
const refLinks = (refs.match(/\[[^\]]+\]\(https?:\/\/[^)]+\)/g) || []).length;
if (refLinks < sel.min_refs) errors.push(`參考連結不足：${refLinks} < ${sel.min_refs}`);
for (const s of sel.selected_sources || []) {
  if (!content.includes(s.link)) errors.push(`參考資料缺少選定來源：${s.title}`);
}
if (!content.includes('本內容由 AI 輔助撰寫、經站方監督，僅供娛樂和文化學習參考')) errors.push('缺少免責聲明');
const BANNED = ['首先', '其次', '總之', '不僅如此', '值得注意的是', '綜上所述', '這提醒我們'];
const hit = BANNED.filter(x => content.includes(x));
if (hit.length) errors.push('使用禁用詞：' + hit.join('、'));
if (/—/.test(content)) errors.push('含破折號');
if (/\p{Extended_Pictographic}/u.test(content)) errors.push('含 Emoji');
if (typeof review.natural !== 'boolean') errors.push('文筆審查結果無法解析');
else if (review.natural === false) errors.push('AI 文筆審查未通過：' + (review.reasons || []).join('；'));
// 站內連結：必須來自清單，不得捏造
const norm = u => { let x = u.replace('://www.', '://'); try { x = decodeURIComponent(x); } catch (e) {} return x.replace(/\/$/, ''); };
const allowed = new Set(plan.linkables.map(l => norm(l.url)));
const internal = [...body.matchAll(/\]\((https?:\/\/(?:www\.)?aiziwei\.online\/(?:zh-TW|en)\/blog\/[^)\s]+)\)/g)].map(m => norm(m[1]));
const bad = internal.filter(u => !allowed.has(u));
if (bad.length) errors.push('站內連結不在舊文清單內：' + bad.join('、'));
const uniq = new Set(internal);
if (uniq.size < sel.min_internal) errors.push(`站內連結不足：${uniq.size} < ${sel.min_internal}`);
if (uniq.size > 5) errors.push(`站內連結過多：${uniq.size} > 5`);
function overlap(s1, s2) {
  const set1 = new Set(s1.split(''));
  const same = s2.split('').filter(c => set1.has(c)).length;
  return same / Math.max(s2.length, 1);
}
for (const t of plan.recentTitles) {
  if (overlap(t, a.title || '') >= 0.6) { errors.push(`標題與近期文章過近：${t}`); break; }
}
return [{ json: { passed: errors.length === 0, errors, article: a } }];

const gate = $input.first().json;
const sel = $('統一選題').first().json;
const base = $('寫作素材').first().json.prompt;
const a = gate.article || {};
const prompt = `${base}

【上一版草稿】
標題：${a.title || ''}

${a.content || ''}

【修改指示】上一版未通過品質檢查。請以這份草稿為基礎修改，保留論點與已經寫好的段落，只改出問題的地方，不要整篇換成另一篇文章。
修改後仍必須：文末保留「## 參考資料」與最後一行免責聲明；內文站內連結至少 ${sel.min_internal} 個（只能用站內舊文清單的網址）；字數 1,800-2,500 字。
未通過的原因：
- ${gate.errors.join('\n- ')}`;
return [{ json: { prompt } }];

