];
// 年度四化文：日期起算 17 天內發布
const ANNUAL = [['2026-11-23','丁未','2027'],['2027-11-22','戊申','2028']];
// 中州派（王亭之）十干四化：祿、權、科、忌
const SIHUA = {
  '甲':['廉貞','破軍','武曲','太陽'],'乙':['天機','天梁','紫微','太陰'],'丙':['天同','天機','文昌','廉貞'],'丁':['太陰','天同','天機','巨門'],
