  '壬':['天梁','紫微','左輔','武曲'],'癸':['破軍','巨門','太陰','貪狼'],
};
const STAR_TAGS = ['紫微','天府','七殺','破軍','貪狼','天機','太陰','天同','天梁','太陽','巨門'];
// 日期給模型用自然寫法，避免 2026-10-08 這種格式被照抄進文章
const MONTHS_EN = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const zhDate = d => { const [y, m, dd] = d.split('-').map(Number); return `${y} 年 ${m} 月 ${dd} 日`; };
const enDate = d => { const [y, m, dd] = d.split('-').map(Number); return `${MONTHS_EN[m - 1]} ${dd}, ${y}`; };
const sihuaOf = stem => { const s = SIHUA[stem]; return { 化祿: s[0], 化權: s[1], 化科: s[2], 化忌: s[3] }; };
const sihuaTags = stem => ['四化', ...SIHUA[stem].filter(x => STAR_TAGS.includes(x))].slice(0, 5);

// 紫微入門連載（依序發布，已有的主星詳解不重複）
const LESSONS = [
  { topic: '四化是什麼：化祿、化權、化科、化忌怎麼流動', tags: ['四化','化祿','化權','化科','化忌'] },
  { topic: '三方四正：為什麼看一個宮位要同時看四個', tags: ['三方四正','命宮','論斷方法'] },
  { topic: '廟旺與落陷：同一顆星為什麼表現天差地遠', tags: ['廟旺','落陷','論斷方法'] },
  { topic: '大限怎麼讀：每十年換一次人生舞台', tags: ['大限','論斷方法','命宮'] },
  { topic: '流年與流月：短期運勢怎麼看才不流於迷信', tags: ['流年','四化','論斷方法'] },
  { topic: '天機星詳解：智慧、變動與想太多', tags: ['天機','命宮','心理'], extra: '十四主星' },
  { topic: '命宮無主星怎麼看：借星安宮的邏輯', tags: ['命宮','格局','論斷方法'] },
  { topic: '煞星不等於壞事：擎羊、陀羅、火星、鈴星的另一面', tags: ['煞星','化解','論斷方法'] },
  { topic: '貪狼星詳解：慾望、才藝與桃花', tags: ['貪狼','感情','命宮'], extra: '十四主星' },
  { topic: '格局是什麼：命盤裡的星曜組合怎麼成局', tags: ['格局','論斷方法','三方四正'] },
  { topic: '巨門星詳解：口才、懷疑與是非', tags: ['巨門','人際','命宮'], extra: '十四主星' },
  { topic: '常見問題：出生時辰不確定，命盤還能看嗎', tags: ['命宮','論斷方法'] },
  { topic: '天梁星詳解：庇蔭、原則與老成', tags: ['天梁','命宮','人際'], extra: '十四主星' },
  { topic: '常見問題：雙胞胎命盤相同，人生為什麼不同', tags: ['論斷方法','大限','命宮'] },
  { topic: '七殺星詳解：魄力、孤獨與開創', tags: ['七殺','事業','命宮'], extra: '十四主星' },
  { topic: '常見問題：農曆閏月出生的人怎麼排盤', tags: ['論斷方法','命宮'] },
];

const SERIES = ['二十四節氣','流月四化','年度四化','人生議題','紫微入門','時事觀點'];
const pubDate = p => String(p.published_at || p.created_at || '').slice(0, 10);
const tagged = (t, days) => posts.some(p => (p.tags || []).includes(t) && diff(today, pubDate(p)) <= days);
// 舊文沒有系列標籤，一律視為時事觀點
const isNews = p => (p.tags || []).includes('時事觀點') || !(p.tags || []).some(t => SERIES.includes(t));
const lastNewsDays = Math.min(...posts.filter(isNews).map(p => diff(today, pubDate(p))), 9999);
// 連載從 2026-10-01 起算；之前的入門舊文不佔講次
const lessonCount = posts.filter(p => (p.tags || []).includes('紫微入門') && pubDate(p) >= '2026-10-01').length;

const warnings = [];
const tableEnd = SOLAR_TERMS[SOLAR_TERMS.length - 1][0];
if (diff(tableEnd, today) < 60) warnings.push(`曆法表將於 ${tableEnd} 用完，請更新「排程決策」節點`);

const term = SOLAR_TERMS.find(([d]) => diff(d, today) >= 0 && diff(d, today) <= 3);
const month = LUNAR_MONTHS.find(([d]) => diff(today, d) <= 6 && diff(d, today) <= 3);
const annual = ANNUAL.find(([d]) => diff(today, d) >= 0 && diff(today, d) <= 17);

let type;
if (FORCE) type = FORCE;
else if (term && !tagged('二十四節氣', 7)) type = 'solar_term';
else if (month && !tagged('流月四化', 20)) type = 'monthly';
else if (annual && !tagged('年度四化', 300)) type = 'annual';
else if (weekday === 4 && lastNewsDays >= 25) type = 'news';
else if (weekday === 4 && lessonCount < LESSONS.length) type = 'lesson';
else type = 'life';

let plan;
if (type === 'solar_term') {
  const t = term || SOLAR_TERMS.find(([d]) => diff(d, today) >= 0);
  plan = {
    route: 'direct', type, type_label: '二十四節氣', series_tag: '二十四節氣',
    topic: `${t[1]}節氣：從紫微斗數看這段時間的身心與節奏`,
    angle: `${t[1]}（${zhDate(t[0])}）前後的季節變化，連結${TERM_FOCUS[t[1]].slice(0, 2).join('與')}所象徵的生活面向，談作息、心態與該留意的事，不談開運、不做吉凶斷語`,
    knowledge_tags: TERM_FOCUS[t[1]], facts: { 節氣: t[1], 日期: zhDate(t[0]), date_en: enDate(t[0]) },
  };
} else if (type === 'monthly') {
  const m = month || LUNAR_MONTHS.find(([d]) => diff(d, today) >= 0);
  const stem = m[2][0];
  plan = {
    route: 'direct', type, type_label: '流月四化', series_tag: '流月四化',
    topic: `農曆${m[1]}（${m[2]}月）流月四化`,
    angle: `本月月干「${stem}」引動的四化星，對命盤中有這些星的人分別意味著什麼；用一句主題帶出本月重點，再說明化祿、化權、化科、化忌各自落在生活哪個面向，並提醒流月必須疊合個人命盤才有意義`,
    knowledge_tags: sihuaTags(stem),
    facts: { 農曆月份: `${m[3]}年${m[1]}`, 月干支: m[2], 起始日: zhDate(m[0]), start_en: enDate(m[0]), 四化: sihuaOf(stem), 理論依據: '中州派（王亭之）十干四化' },
  };
} else if (type === 'annual') {
  const a = annual || ANNUAL.find(([d]) => diff(d, today) >= 0);
  const stem = a[1][0];
  plan = {
    route: 'direct', type, type_label: '年度四化', series_tag: '年度四化',
    topic: `${a[2]} ${a[1]}年流年四化總覽`,
    angle: `${a[1]}年天干「${stem}」的流年四化，對整體氛圍與不同命盤結構的人各有什麼意義；避免生肖排名式的吉凶預言`,
    knowledge_tags: sihuaTags(stem),
    facts: { 年份: `${a[2]}（${a[1]}年）`, 四化: sihuaOf(stem), 理論依據: '中州派（王亭之）十干四化' },
  };
} else if (type === 'lesson') {
  const l = LESSONS[lessonCount % LESSONS.length];
  plan = {
    route: 'direct', type, type_label: '紫微入門', series_tag: l.extra ? `紫微入門,${l.extra}` : '紫微入門',
    topic: l.topic, angle: '寫給完全沒學過紫微斗數的讀者，用生活例子講清楚一個概念，並說明常見誤解',
    knowledge_tags: l.tags, facts: { 連載: `紫微入門第 ${lessonCount + 1} 講` },
  };
} else if (type === 'news') {
  plan = { route: 'news', type, type_label: '時事觀點', series_tag: '時事觀點' };
} else {
  plan = { route: 'life', type: 'life', type_label: '人生議題', series_tag: '人生議題' };
}

plan.make_english = plan.type !== 'news';
plan.min_refs = plan.type === 'news' ? 2 : plan.type === 'life' ? 1 : 0;

const linkables = posts.map(p => ({
  title: p.title,
  url: 'https://aiziwei.online' + (p.url || `/zh-TW/blog/${p.slug}`),
  tags: (p.tags || []).filter(t => t !== '紫微斗數' && t !== 'AI紫微斗數').slice(0, 5),
}));
plan.min_internal = linkables.length >= 5 ? 2 : 0;

return [{ json: {
  route: plan.route, plan, today, warnings,
  recentTitles: posts.slice(0, 15).map(p => p.title),
  linkables: linkables.slice(0, 40),
} }];

// 國際命理部落格 RSS（不含台灣、中國、香港來源）
const FEEDS = [
  { site: 'Natalia Pugacheva', country: '俄羅斯', url: 'https://npugacheva.com/feed/' },
  { site: 'Joey Yap', country: '馬來西亞', url: 'https://home.joeyyap.com/feed/' },
  { site: 'RenerQi', country: '馬來西亞', url: 'https://www.renerqi.com/feed/' },
  { site: 'Master Sean Chan', country: '新加坡', url: 'https://www.masterseanchan.com/feed/' },
  { site: 'Singapore Feng Shui Master', country: '新加坡', url: 'https://tcfengshui.com/feed/' },
  { site: 'Fengshui Discovery', country: '新加坡', url: 'https://www.fengshuidiscovery.com/blog?format=rss' },
];
return FEEDS.map(f => ({ json: f }));

// 解析國際 RSS（HTTP 回傳純文字 XML），近 120 天、每站最多 4 篇、總數最多 24 篇
const feeds = $('國際來源清單').all().map(i => i.json);
const now = Date.now();
const WINDOW = 120 * 86400000;
const strip = s => String(s || '').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').replace(/<[^>]+>/g, ' ')
  .replace(/&amp;/g, '&').replace(/&#8217;|&rsquo;/g, "'").replace(/&#8220;|&#8221;|&quot;/g, '"').replace(/&#\d+;|&[a-z]+;/g, ' ')
  .replace(/\s+/g, ' ').trim();
const pick = (block, tag) => { const m = block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`, 'i')); return m ? m[1] : ''; };
const candidates = [];
const failed = [];
$input.all().forEach((item, idx) => {
  const feed = feeds[idx] || {};
  const xml = typeof item.json.data === 'string' ? item.json.data : '';
  if (!xml) { failed.push(feed.site); return; }
  const blocks = xml.match(/<item[\s>][\s\S]*?<\/item>|<entry[\s>][\s\S]*?<\/entry>/gi) || [];
  let n = 0;
  for (const b of blocks) {
    const title = strip(pick(b, 'title'));
    let link = strip(pick(b, 'link'));
    if (!link) { const m = b.match(/<link[^>]*href="([^"]+)"/i); link = m ? m[1] : ''; }
    const date = strip(pick(b, 'pubDate') || pick(b, 'published') || pick(b, 'updated'));
    const t = Date.parse(date);
    if (!title || !/^https?:\/\//.test(link) || !t || now - t > WINDOW) continue;
    candidates.push({ site: feed.site, country: feed.country, title, link, date: new Date(t).toISOString().slice(0, 10),
      snippet: strip(pick(b, 'description') || pick(b, 'summary')).slice(0, 300) });
    if (++n >= 4) break;
  }
});
return [{ json: { candidates: candidates.slice(0, 24), failed } }];

const plan = $('排程決策').first().json;
const { candidates } = $input.first().json;
const prompt = `近期國際命理部落格文章（可選 0-2 篇具名引述，也可以都不用）：
${JSON.stringify(candidates, null, 1)}

近期已發文標題（新主題不得與其語意重複）：
${JSON.stringify(plan.recentTitles)}`;
return [{ json: { prompt, candidates } }];

