} catch (e) { review = {}; }
const ctx = $('英文素材').first().json;
const sel = $('統一選題').first().json;
const errors = [];
const content = a.content || '';
const words = (content.match(/[A-Za-z][A-Za-z'-]*/g) || []).length;
if (words < 900) errors.push(`Too short: ${words} < 900 words`);
const refIdx = content.indexOf('## References');
if (refIdx === -1) errors.push('Missing "## References" section');
const body = refIdx === -1 ? content : content.slice(0, refIdx);
const refs = refIdx === -1 ? '' : content.slice(refIdx);
const refLinks = (refs.match(/\[[^\]]+\]\(https?:\/\/[^)]+\)/g) || []).length;
if (refLinks < sel.min_refs) errors.push(`Not enough reference links: ${refLinks} < ${sel.min_refs}`);
for (const s of sel.selected_sources || []) {
  if (!content.includes(s.link)) errors.push(`References missing source: ${s.title}`);
}
if (!content.includes('This content was AI-assisted and reviewed by our editorial team. For entertainment and cultural reference only.')) errors.push('Missing disclaimer');
const cjk = (content.match(/[一-鿿]/g) || []).length;
